"""All-cohort author development tables from the unchanged frozen report."""
from pathlib import Path
from fractions import Fraction as F
import json,collections
ROOT=Path(__file__).resolve().parents[1]
def rows(p):return [json.loads(x) for x in p.read_text().splitlines() if x.strip()]
def fmt(x,k=6,up=False):
 x=F(x);scale=10**k;n=-((-x.numerator*scale)//x.denominator) if up else x.numerator*scale//x.denominator
 sign='-' if n<0 else '';n=abs(n);return f'{sign}{n//scale}.{n%scale:0{k}d}'
def main():
 data=rows(ROOT/'results126/report01/cohorts_summary126.jsonl');pairs=rows(ROOT/'results126/independent01/policy_pairs126.jsonl');s=json.loads((ROOT/'results126/report01/SUMMARY126.json').read_text())
 out=[r'\section{Complete current decision-service results}\label{dev:service126}',r'The tables retain all 176 prespecified cohorts and both contemporaneous comparisons at every test state. Abbreviations are F (fused), W (warm adaptive), D (direct terminal), G (33-action DP), V (value fit), M (marginal fit), and O (online or no fit). A cohort comprises nine original economic states. All mean original-policy intervals are rounded outward; regret and action-distance displays are upper bounds. No row is selected by observed performance.',r'\subsection{Independent economic pair comparisons}',r'\begin{center}\begin{tabular}{lrrrr}\toprule',r'Comparator & Direct gain & Direct loss & Exact tie & Unresolved\\\midrule']
 for comp in ['fused_control','warm_adaptive']:
  rr=[r for r in pairs if r['comparator']==comp]
  out.append(comp.replace('_',' ')+f" & {sum(r['direct_strictly_better'] for r in rr)} & {sum(r['control_strictly_better'] for r in rr)} & {sum(r['same_complete_policy'] for r in rr)} & {sum(r['unresolved_order'] for r in rr)} \\\\")
 out += [r'\bottomrule\end{tabular}\end{center}',r'The independent ordinary regret threshold is satisfied for all 1,584 decisions; the frozen independent summary does not itself recheck the separate width gate. Confirmation of the tighter reported regret succeeds for 1,277, interval containment for 471, and the stronger independent target for 1,175. There are zero contradictions, 307 unresolved reported-regret checks, 1,113 unresolved containment checks and 250 unresolved pair orderings. All 515 distinct original policies receive their prescribed initial evaluation; the cap ends at 32,740 contexts, not at an outcome-chosen precision.',r'\subsection{Every cohort: original values and decision accuracy}',r'\begingroup\small\setlength{\tabcolsep}{3pt}',r'\begin{longtable}{rrllcrrr}\toprule',r'Risk & Mesh & Representation & Fit & Route & Target/9 & Mean lower & Mean upper\\\midrule\endhead']
 modes={'fused_control':'F','warm_adaptive':'W','direct_terminal':'D','grid33':'G'}
 for r in data:
  loss={'value':'V','marginal':'M'}.get(r['training_loss'],'O');arm='DP' if r['arm']=='uniform_dp' else r['arm'];out.append(f"{(.5,.75)[r['index']]:.2f} & {r['budget']} & {arm} & {loss} & {modes[r['mode']]} & {r['stronger_target']} & {fmt(r['cost_lower'])} & {fmt(r['cost_upper'],up=True)} \\\\")
 out += [r'\bottomrule\end{longtable}\endgroup',r'\subsection{Every cohort: regret bounds and complete first-state cost}',r'The seconds interval uses the minimum and maximum of all three complete first-state process allocations. The acquisition column is the retained original component allocation, including the required parent charge for matched hinges. These are not nine-state timing intervals and do not include an imputed value for unknown historical interrupted parent clocks.',r'\begingroup\small\setlength{\tabcolsep}{2.5pt}',r'\begin{longtable}{rrllcrrr}\toprule',r'Risk & Mesh & Representation & Fit & Route & Mean regret & Seconds range & Acquisition\\\midrule\endhead']
 for r in data:
  loss={'value':'V','marginal':'M'}.get(r['training_loss'],'O');arm='DP' if r['arm']=='uniform_dp' else r['arm'];out.append(f"{(.5,.75)[r['index']]:.2f} & {r['budget']} & {arm} & {loss} & {modes[r['mode']]} & {fmt(r['mean_regret_bound'],8,True)} & [{float(F(r['timing_min'])):.5f},{float(F(r['timing_max'])):.5f}] & {float(F(r['acquisition'])):.4f} \\\\")
 out += [r'\bottomrule\end{longtable}\endgroup',r'\subsection{All counted work and custody}',r'The primary parent process includes 120.119 seconds, of which 120.020 seconds are the measured child execution. Three complete first-state timing processes total '+f"{float(F(s['complete_timing_parent_seconds'])):.6f}"+r' seconds. Saved algebra verification, independent rational economics, exact action-distance verification, full-support computation, fitting and later cached-geometry work each retain separate launch and execution receipts. The original counters include terminal and midpoint work, cubic regions, derivatives, risk sorting, proposals, rejected candidates, new-support attempts and fallback. Machine-readable cohort summaries contain every counter and the complete research ledger is in the referee-ready package.',r'All 96 sufficient neural adoption regions are empty. Their 96 optimistic interval regions remain nonempty; separately, every case has a conventional exactly identical policy with a strict conservative cost advantage for each positive computation price under the measured ranges. Both classifications are retained. No new state-distribution inference or calibrated adoption claim follows.']
 (ROOT/'new126/development_results126.tex').write_text('\n\n'.join(out)+'\n')
 print(json.dumps({'cohorts':len(data),'pairs':len(pairs),'output':'new126/development_results126.tex'}))
if __name__=='__main__':main()
